      ko: [{icon:"🍚", t:"태국 찹쌀", d:"쪄도 모양을 유지하는 찰진 품종"}, {icon:"🥭", t:"남독마이 망고", d:"잘 익은 노란 태국 품종 — 전통 조합"}, {icon:"🥥", t:"3분의 2와 3분의 1", d:"단 코코넛은 밥에, 짠 토핑은 위에"}, {icon:"⏱️", t:"15분 휴지", d:"핵심 단계 — 쌀이 밀크를 마셔 진주 푸딩으로"}],
